 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    blocks = []
    # The 3x3 monochrome objects are the line emitters.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                cells = {(rr, cc) for rr in range(r, r + 3) for cc in range(c, c + 3)}
                if cells.isdisjoint(seen):
                    blocks.append((r + 1, c + 1, color))
                    seen.update(cells)

    # Record the colors of all emitter rays passing through each cell.
    rays = {}
    for r, c, color in blocks:
        for cc in range(w):
            rays.setdefault((r, cc), set()).add(color)
        for rr in range(h):
            rays.setdefault((rr, c), set()).add(color)

    out = [row[:] for row in grid]
    for (r, c), colors in rays.items():
        # Different-colored rays cancel where they intersect.
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
